#ifndef DSKGEN_DEV_Q4K_HEADER
#define DSKGEN_DEV_Q4K_HEADER
__device__ __forceinline__ unsigned q4k_byte(uint4 h, unsigned k) {
    const unsigned w = k < 4 ? h.y : k < 8 ? h.z : h.w;
    return (w >> (8 * (k & 3))) & 255;
}
__device__ __forceinline__ void q4k_scale_min(uint4 h, unsigned g, float &sc, float &m) {
    if (g < 4) { sc = (float)(q4k_byte(h, g) & 63); m = (float)(q4k_byte(h, g + 4) & 63); }
    else {
        const unsigned hi = q4k_byte(h, g + 4);
        sc = (float)((hi & 15) | ((q4k_byte(h, g - 4) >> 6) << 4));
        m = (float)((hi >> 4) | ((q4k_byte(h, g) >> 6) << 4));
    }
}
#endif
#ifndef DSKGEN_DEV_Q4K_BLOCK_FLOAT
#define DSKGEN_DEV_Q4K_BLOCK_FLOAT
/* One block's contribution for this lane: lane l holds nibble word q = bytes
 * c*32 + (l%8)*4 .. +3 of the block, i.e. values c*64 + o .. o+3 (low
 * nibbles, sub-block 2c) and c*64 + 32 + o .. (high nibbles, sub-block 2c+1). */
__device__ __forceinline__ float q4k_block(uint4 h, unsigned q, float4 xa, float4 xb, unsigned c) {
    const float d = __half2float(__ushort_as_half((unsigned short)(h.x & 0xffff)));
    const float dm = __half2float(__ushort_as_half((unsigned short)(h.x >> 16)));
    float s0, m0, s1, m1;
    q4k_scale_min(h, 2 * c, s0, m0);
    q4k_scale_min(h, 2 * c + 1, s1, m1);
    const float lo = (float)(q & 15) * xa.x + (float)((q >> 8) & 15) * xa.y +
                     (float)((q >> 16) & 15) * xa.z + (float)((q >> 24) & 15) * xa.w;
    const float hi = (float)((q >> 4) & 15) * xb.x + (float)((q >> 12) & 15) * xb.y +
                     (float)((q >> 20) & 15) * xb.z + (float)(q >> 28) * xb.w;
    return d * (s0 * lo + s1 * hi) - dm * (m0 * (xa.x + xa.y + xa.z + xa.w) + m1 * (xb.x + xb.y + xb.z + xb.w));
}
#endif
#ifndef DSKGEN_DEV_DPP_XOR
#define DSKGEN_DEV_DPP_XOR
#if defined(__gfx1151__)
template<int MASK>
__device__ __forceinline__ float dpp_xor(float x) {
    return __int_as_float(__builtin_amdgcn_update_dpp(0, __float_as_int(x), 0x160 | MASK, 0xf, 0xf, true));
}
#endif
#endif
#ifndef DSKGEN_DEV_WAVE_SUM
#define DSKGEN_DEV_WAVE_SUM
__device__ __forceinline__ float wave_sum(float x) {
#if defined(__gfx1151__)
    x += __int_as_float(__builtin_amdgcn_permlanex16(__float_as_int(x), __float_as_int(x), 0x76543210, 0xFEDCBA98, true, false));
    x += dpp_xor<8>(x);
    x += dpp_xor<4>(x);
    x += dpp_xor<2>(x);
    x += dpp_xor<1>(x);
#else
    for (int d = 16; d; d >>= 1) x += __shfl_xor(x, d, 32);
#endif
    return x;
}
#endif
#ifndef DSKGEN_DEV_SILU
#define DSKGEN_DEV_SILU
__device__ __forceinline__ float sigmoid(float x) {
    const float e = expf(-fabsf(x));
    return x >= 0 ? 1.0f / (1.0f + e) : e / (1.0f + e);
}
__device__ __forceinline__ float silu(float x) { return x * sigmoid(x); }
#endif
#ifndef DSKGEN_DEV_Q8_VALUE4
#define DSKGEN_DEV_Q8_VALUE4
/* Values i .. i+3 (i % 4 == 0) of a Q8_0 row: block i/32 of 34 bytes, an f16
 * scale then 32 int8 codes; each value is one rounding of code * scale. */
__device__ __forceinline__ float4 q8_value4(const char *row, unsigned i) {
    const char *b = row + (i / 32) * 34;
    const float scale = __half2float(*(const __half *)b);
    const uint16_t *q = (const uint16_t *)(b + 2 + i % 32);
    return make_float4((float)(int8_t)q[0] * scale, (float)(int8_t)(q[0] >> 8) * scale,
                       (float)(int8_t)q[1] * scale, (float)(int8_t)(q[1] >> 8) * scale);
}
#endif
#ifndef DSKGEN_DEV_Q8_DOT
#define DSKGEN_DEV_Q8_DOT
__device__ __forceinline__ float q8_dot(const char *row, const float *x, unsigned n) {
    float acc = 0;
    for (unsigned i = (threadIdx.x & 31) * 4; i < n; i += 128) {
        const float4 w = q8_value4(row, i), v = *(const float4 *)(x + i);
        acc += w.x * v.x; acc += w.y * v.y; acc += w.z * v.z; acc += w.w * v.w;
    }
    return wave_sum(acc);
}
/* NR rows against one x, the loads of all rows issued together; each row's
 * sum in q8_dot's order. */
template<unsigned NR>
__device__ __forceinline__ void q8_dot_n(const char *const *rows, const float *x, unsigned n, float *out) {
    float acc[NR];
    #pragma unroll
    for (unsigned r = 0; r < NR; r++) acc[r] = 0;
    #pragma unroll 4
    for (unsigned i = (threadIdx.x & 31) * 4; i < n; i += 128) {
        const float4 v = *(const float4 *)(x + i);
        #pragma unroll
        for (unsigned r = 0; r < NR; r++) {
            const float4 w = q8_value4(rows[r], i);
            acc[r] += w.x * v.x; acc[r] += w.y * v.y; acc[r] += w.z * v.z; acc[r] += w.w * v.w;
        }
    }
    #pragma unroll
    for (unsigned r = 0; r < NR; r++) out[r] = wave_sum(acc[r]);
}
#endif

